import { describe, test, expect } from "vitest";
import PQueue from "../source/index.js";

describe("p-queue regression", () => {
  test("basic queue", async () => {
    const queue = new PQueue({ concurrency: 2 });
    const results: number[] = [];
    await queue.add(() => { results.push(1); return Promise.resolve(); });
    await queue.add(() => { results.push(2); return Promise.resolve(); });
    await queue.onIdle();
    expect(results).toEqual([1,2]);
  });
  test("concurrency", async () => {
    const queue = new PQueue({ concurrency: 1 });
    let running = 0;
    let max = 0;
    const task = async () => { running++; max = Math.max(max, running); await new Promise(r=>setTimeout(r,10)); running--; };
    await Promise.all([queue.add(task), queue.add(task), queue.add(task)]);
    expect(max).toBe(1);
  });

  test("abort signal while queued rejects task and removes from queue", async () => {
    const queue = new PQueue({ concurrency: 1 });
    const controller = new AbortController();
    const results: number[] = [];

    // First task will block the queue
    const firstTask = queue.add(() => {
      results.push(1);
      return new Promise<void>(resolve => setTimeout(resolve, 100));
    });

    // Second task will be queued - we'll abort it while waiting
    const secondTaskPromise = queue.add(() => {
      results.push(2);
      return Promise.resolve();
    }, { signal: controller.signal });

    // Abort the second task while it's queued
    controller.abort();

    // Second task should reject with AbortError
    await expect(secondTaskPromise).rejects.toThrow(/aborted/);

    // Wait for first task to complete
    await firstTask;
    await queue.onIdle();

    // Only the first task should have run
    expect(results).toEqual([1]);
    expect(queue.size).toBe(0);
  });

  test("abort signal before add rejects immediately without enqueueing", async () => {
    const queue = new PQueue({ concurrency: 1 });
    const controller = new AbortController();
    const results: number[] = [];

    // First task will block the queue
    const firstTask = queue.add(() => {
      results.push(1);
      return new Promise<void>(resolve => setTimeout(resolve, 100));
    });

    // Abort before adding the second task
    controller.abort();

    // Second task should reject immediately
    const secondTaskPromise = queue.add(() => {
      results.push(2);
      return Promise.resolve();
    }, { signal: controller.signal });

    await expect(secondTaskPromise).rejects.toThrow(/aborted/);

    // Wait for first task to complete
    await firstTask;
    await queue.onIdle();

    // Only the first task should have run
    expect(results).toEqual([1]);
  });
});

